def fn(x, kh, kw, stride):
    N,C,H,W = x.shape
    oh=(H-kh)//stride+1; ow=(W-kw)//stride+1
    c = x.unfold(2,kh,stride).unfold(3,kw,stride)
    return c.permute(0,2,3,1,4,5).reshape(N*oh*ow, C*kh*kw)

def fn(ids, table):
    ids = ids.long().reshape(-1)
    mask = (ids[:, None] == torch.arange(table.shape[0], device=table.device)).to(table.dtype)
    return (mask[:, :, None] * table[None, :, :]).sum(dim=1)

def fn(ids, num_classes):
    out = torch.zeros(ids.shape[0], num_classes, dtype=torch.float32, device=ids.device)
    return out.scatter_(1, ids.long().view(-1, 1), 1.0)

def fn(W, bits, per_row):
    s = W.abs().amax(dim=1) / (2**(bits-1) - 1)
    return s

def fn(W, rank):
    U, S, Vh = torch.linalg.svd(W, full_matrices=False)
    return U[:, :rank], S[:rank], Vh[:rank, :]
